// Order records, written at checkout and read/managed by the employee
// dashboard. Payment itself is still mocked (see app/checkout/page.tsx),
// but the order record — including its status — is real once Supabase is
// configured.
import { supabase } from "./supabase";
import { staffFetch } from "./staff-auth";

export type OrderItem = { id: string; name: string; price: number; qty: number };

export type OrderStatus = "new" | "preparing" | "ready" | "completed";

export const ORDER_STATUSES: OrderStatus[] = ["new", "preparing", "ready", "completed"];

export type Order = {
  id: string;
  created_at: string;
  fulfillment: "pickup" | "delivery";
  items: OrderItem[];
  subtotal: number;
  status: OrderStatus;
  phone?: string | null;
  clover_order_id?: string | null;
  clover_push_error?: string | null;
  delivery_address?: DeliveryAddressFields | null;
  delivery_fee?: number | null;
  service_fee?: number | null;
  uber_delivery_id?: string | null;
  uber_status?: string | null;
  uber_tracking_url?: string | null;
  uber_courier?: { name?: string; vehicle_type?: string; phone_number?: string } | null;
  uber_error?: string | null;
  // Online payment + refunds (supabase/refunds.sql).
  stripe_session_id?: string | null;
  // Clover Hosted Checkout payments (supabase/clover-payments.sql).
  payment_provider?: "stripe" | "clover" | null;
  clover_payment_id?: string | null;
  refunded_amount?: number | null;
  refunded_items?: { id: string; qty: number }[] | null;
  refund_status?: "partial" | "full" | null;
  refunded_at?: string | null;
  contains_alcohol?: boolean | null; // wine/beer — check 21+ ID (supabase/alcohol.sql)
};

export type DeliveryAddressFields = {
  name: string;
  street: string;
  apt?: string;
  city: string;
  state: string;
  zip: string;
  notes?: string;
};

export async function createOrder(order: {
  fulfillment: "pickup" | "delivery";
  items: OrderItem[];
  subtotal: number;
  phone?: string | null;
  delivery_address?: DeliveryAddressFields | null;
  delivery_fee?: number | null;
  service_fee?: number | null;
}) {
  if (!supabase) return;
  const { error } = await supabase.from("orders").insert(order);
  if (error) console.error("createOrder:", error.message);
}

// 300 (rather than a smaller number) so the dashboard's analytics tab has
// enough history for a "today vs. yesterday" comparison and a same-day
// hourly breakdown even on a busy day, without needing a second query.
export async function getOrders(limit = 300): Promise<Order[]> {
  if (!supabase) return [];

  const BASE =
    "id, created_at, fulfillment, items, subtotal, status, phone, clover_order_id, clover_push_error, delivery_address, delivery_fee, service_fee, uber_delivery_id, uber_status, uber_tracking_url, uber_courier, uber_error, stripe_session_id";
  const REFUNDS = "refunded_amount, refunded_items, refund_status, refunded_at";
  const first = await supabase
    .from("orders")
    .select(`${BASE}, ${REFUNDS}, contains_alcohol, payment_provider, clover_payment_id`)
    .order("created_at", { ascending: false })
    .limit(limit);
  let data = first.data as Record<string, unknown>[] | null;
  let error = first.error;
  if (error) {
    // supabase/clover-payments.sql not run yet.
    const retry = await supabase
      .from("orders")
      .select(`${BASE}, ${REFUNDS}, contains_alcohol`)
      .order("created_at", { ascending: false })
      .limit(limit);
    data = retry.data as Record<string, unknown>[] | null;
    error = retry.error;
  }
  if (error) {
    // supabase/alcohol.sql not run yet — try without contains_alcohol.
    const retry = await supabase.from("orders").select(`${BASE}, ${REFUNDS}`).order("created_at", { ascending: false }).limit(limit);
    data = retry.data as Record<string, unknown>[] | null;
    error = retry.error;
  }
  if (error) {
    // supabase/refunds.sql not run yet — load orders without the refund columns.
    const retry = await supabase.from("orders").select(BASE).order("created_at", { ascending: false }).limit(limit);
    data = retry.data as Record<string, unknown>[] | null;
    error = retry.error;
  }

  if (error || !data) {
    if (error) console.error("getOrders:", error.message);
    return [];
  }

  return data.map((row) => ({
    ...row,
    subtotal: Number(row.subtotal),
    delivery_fee: row.delivery_fee === null || row.delivery_fee === undefined ? null : Number(row.delivery_fee),
    service_fee: row.service_fee === null || row.service_fee === undefined ? null : Number(row.service_fee),
    refunded_amount: row.refunded_amount != null ? Number(row.refunded_amount) : 0,
    status: (row.status ?? "new") as OrderStatus,
  })) as Order[];
}

export async function updateOrderStatus(id: string, status: OrderStatus): Promise<boolean> {
  if (!supabase) return false;
  const { error } = await supabase.from("orders").update({ status }).eq("id", id);
  if (error) {
    console.error("updateOrderStatus:", error.message);
    return false;
  }
  return true;
}

// A single count, not the order contents — used on the public storefront to
// show a live "X orders ahead of you" estimate without exposing anything
// about what's actually in those orders.
export async function getActiveOrderCount(): Promise<number> {
  if (!supabase) return 0;
  // Customers can't read the orders table itself (it holds phone numbers),
  // so this asks a database function for just the count — see
  // active_order_count() in supabase/staff-login.sql.
  const { data, error } = await supabase.rpc("active_order_count");
  if (error) {
    console.error("getActiveOrderCount:", error.message);
    return 0;
  }
  return Number(data ?? 0);
}

// Best-effort text to the customer when their order's marked Ready. Only
// fires when they left a phone number, and only actually sends once Twilio
// is configured (see lib/twilio.ts / the README's SMS section) — otherwise
// this silently no-ops, the same way Clover sync no-ops until connected.
export async function notifyOrderReady(orderId: string, phone?: string | null) {
  if (!phone) return;
  try {
    await staffFetch("/api/notify/order-ready", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ orderId, phone }),
    });
  } catch {
    // best-effort — an order still gets marked Ready even if this fails
  }
}
